class Secret {
private:
    int code;
public:
    Secret(int c) : code(c) {}
};

int main() {
    Secret s(42);
    s.code = 100; // Error: 'code' is private
    return 0;
}

int main() {
    const int x = 10;
    x = 20; // Error: assignment of read-only variable 'x'
    return 0;
}

