// undeclared_template.cpp
// Week 7 Sample: Tests AST context around template and scope errors.

#include <iostream>
#include <vector>

template <typename T>
T square(T val) {
    return val * val;
}

int main() {
    // Error 1: using undeclared variable inside a template call
    std::cout << square(badVar) << std::endl;

    // Error 2: calling the wrong overload (type mismatch)
    std::vector<int> nums;
    nums.push_back("not an int");

    // Error 3: missing semicolon before closing brace
    int result = square(4)
    return 0;
}

